fn is_prime(candidate: u64) -> bool {
    if candidate <= 1 {
        return false; // Not prime
    }
    if candidate == 2 {
        return true; // 2 is prime
    }
    if candidate % 2 == 0 {
        return false; // Even number greater than 2 is not prime
    }
    
    let limit = (candidate as f64).sqrt() as u64; // Calculate the square root
    for i in (3..=limit).step_by(2) { // Check odd numbers only
        if candidate % i == 0 {
            return false; // Found a divisor
        }
    }
    
    true // No divisors found, candidate is prime
}

